def compound_interest(principal, rate, years):
    """Final amount for annually-compounded interest, rounded to 2 decimals.

    `rate` is a percent (5 means 5%). Raises ValueError if principal or
    years is negative. Example: compound_interest(1000, 5, 3) == 1157.63.
    """
    if principal < 0 or years < 0:
        raise ValueError("principal and years must be non-negative")
    return round(principal * (1 + rate / 100) ** years, 2)
